        if tier:
            plan.features = tier[2]
            update_fields.append("features")
        plan.save(update_fields=update_fields)
        aliases = {"home": "homepage", "homepage": "homepage", "marketplace": "marketplace", "lost-found": "lost_found", "lost_found": "lost_found", "announcements": "announcements"}
        campaign_batch = []
        for campaign in Campaign.objects.filter(package_id=plan.pk).iterator(chunk_size=500):
            selected = [aliases[page] for page in (campaign.pages or []) if page in aliases and aliases[page] in pages]
            selected = list(dict.fromkeys(selected))[:plan.max_pages] or pages[:plan.max_pages]
            campaign.pages = selected
            campaign_batch.append(campaign)
            if len(campaign_batch) >= 500:
                Campaign.objects.bulk_update(campaign_batch, ("pages",))
                campaign_batch.clear()
        if campaign_batch:
            Campaign.objects.bulk_update(campaign_batch, ("pages",))


